import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { X, ArrowLeft, ArrowRight, Check, Sparkles, Monitor, Smartphone, Eye, FileText, Type, CircleDollarSign, Search, ListChecks, LayoutList, WandSparkles } from 'lucide-react';
import { useTheme } from '../../context/ThemeContext';
import { werseeAi } from '../../ai/client';
import { createListingDraftSchema } from '../../lib/listingSchemas';
import { CodexActivityPills, CodexComposer, CodexExpandableActivityPill, type CodexComposerMenuItem } from '../ai/CodexAiPrimitives';

interface WizardLayoutProps {
  title: string;
  stepTitle?: string;
  stepDescription?: string;
  stepLabels?: readonly string[];
  steps?: readonly { label: string; required?: boolean }[];
  currentStep: number;
  totalSteps: number;
  onClose: () => void;
  onBack: () => void;
  onNext: () => void;
  isFirstStep: boolean;
  isLastStep: boolean;
  children: React.ReactNode;
  loading?: boolean;
  variant?: 'modal' | 'fullscreen';
  preview?: React.ReactNode | ((type: 'card' | 'page' | 'email' | 'checkout', isDark: boolean) => React.ReactNode);
  onAiGenerate?: (prompt: string) => Promise<void>;
  aiKind?: 'product' | 'digital' | 'course' | 'physical' | 'service' | 'community' | 'job' | 'announcement' | 'bundle' | 'pos_item';
  aiCurrentDraft?: Record<string, unknown>;
  onAiApply?: (patch: Record<string, unknown>) => void;
}

export const WizardLayout = ({
  title,
  stepTitle,
  stepDescription,
  stepLabels,
  steps,
  currentStep,
  totalSteps,
  onClose,
  onBack,
  onNext,
  isFirstStep,
  isLastStep,
  children,
  loading = false,
  variant = 'modal',
  preview,
  onAiGenerate,
  aiKind,
  aiCurrentDraft = {},
  onAiApply,
}: WizardLayoutProps) => {
  const { isDark } = useTheme();
  const hasAiAssistant = Boolean((aiKind && onAiApply) || onAiGenerate);
  const [previewType, setPreviewType] = React.useState<'card' | 'page' | 'email' | 'checkout'>('page');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const isPreviewDark = true;
  const [isMobile, setIsMobile] = useState(false);
  const [showAiPrompt, setShowAiPrompt] = useState(hasAiAssistant);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [activeAiAction, setActiveAiAction] = useState('Ready to help with every step');
  const [activeAiToolName, setActiveAiToolName] = useState<string>();
  const [aiProposal, setAiProposal] = useState<Record<string, unknown> | null>(null);
  const [selectedAiFields, setSelectedAiFields] = useState<string[]>([]);
  const [recentAiFields, setRecentAiFields] = useState<string[]>([]);
  const [aiError, setAiError] = useState('');
  const wizardSteps = React.useMemo(() => Array.from({ length: totalSteps }, (_, index) => ({
    label: steps?.[index]?.label || stepLabels?.[index] || `Step ${index + 1}`,
    required: steps?.[index]?.required !== false,
  })), [stepLabels, steps, totalSteps]);
  const activeStep = wizardSteps[currentStep - 1];
  const activeStepTitle = stepTitle || activeStep?.label;
  const aiQuickActions = [
    { label: 'Create complete draft', description: 'Shape the full listing from your idea', prompt: 'Create a complete, polished draft from my idea and preserve any useful fields I already wrote.', icon: WandSparkles, toolName: 'listing.create_draft' },
    { label: 'Generate title', description: 'Write a clear, specific title', prompt: 'Focus on generating a clear, specific, conversion-friendly title. Preserve my other completed fields.', icon: Type, toolName: 'listing.generate_title' },
    { label: 'Write description', description: 'Build detailed, trustworthy copy', prompt: 'Write a detailed product description and short description. Preserve my other completed fields.', icon: FileText, toolName: 'listing.write_description' },
    { label: 'Recommend price', description: 'Position a realistic offer', prompt: 'Recommend a realistic price and optional original price. Explain the positioning in the generated copy, without inventing sales data.', icon: CircleDollarSign, toolName: 'listing.recommend_price' },
    { label: 'Generate SEO', description: 'Prepare title and meta description', prompt: 'Generate a concise SEO title and meta description. Preserve my other completed fields.', icon: Search, toolName: 'listing.generate_seo' },
    ...(aiKind === 'course' || aiKind === 'digital' ? [{ label: 'Build course structure', description: 'Create modules and practical lessons', prompt: 'Build a practical curriculum with modules and lessons for this course or digital learning product.', icon: LayoutList, toolName: 'listing.build_curriculum' }] : []),
    { label: 'Improve conversion', description: 'Clarify benefits and the offer', prompt: 'Improve the title, benefits, features, FAQs and offer clarity without inventing performance metrics.', icon: ListChecks, toolName: 'listing.improve_conversion' },
    { label: 'Fill remaining fields', description: 'Complete only what is missing', prompt: 'Fill only missing or incomplete fields and preserve useful user-written content.', icon: Check, toolName: 'listing.fill_fields' },
    { label: 'Review entire listing', description: 'Check trust, SEO and completeness', prompt: 'Review the entire draft for completeness, consistency, trust, SEO and conversion clarity, then propose only justified changes.', icon: ListChecks, toolName: 'listing.review' },
  ];

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 1024);
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  useEffect(() => {
    const handleFocus = (e: FocusEvent) => {
      const target = e.target as HTMLElement;
      if (isMobile && (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement)) {
        setTimeout(() => {
          target.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }, 300);
      }
    };
    window.addEventListener('focusin', handleFocus);
    return () => window.removeEventListener('focusin', handleFocus);
  }, [isMobile]);

  const runAiGeneration = async (prompt: string, actionLabel = 'Working on your request', toolName = 'listing.create_draft') => {
    const normalizedPrompt = prompt.trim();
    if (normalizedPrompt.length < 3) {
      setActiveAiAction('Add a little more detail');
      setActiveAiToolName(undefined);
      setAiError('Describe what you want in at least 3 characters.');
      return;
    }
    if (normalizedPrompt.length > 6000) {
      setActiveAiAction('Shorten your request');
      setActiveAiToolName(undefined);
      setAiError('Keep your listing request under 6,000 characters.');
      return;
    }
    setActiveAiAction(actionLabel);
    setActiveAiToolName(toolName);
    setIsAiLoading(true);
    setAiError('');
    try {
      if (aiKind && onAiApply) {
        const response = await werseeAi.generateListingDraft({ kind: aiKind, idea: normalizedPrompt, currentDraft: aiCurrentDraft });
        const proposal = createListingDraftSchema.parse(response.draft) as Record<string, unknown>;
        setAiProposal(proposal);
        setSelectedAiFields(Object.keys(proposal).filter((key) => JSON.stringify(proposal[key]) !== JSON.stringify(aiCurrentDraft[key])));
      } else if (onAiGenerate) {
        await onAiGenerate(normalizedPrompt);
      }
    } catch (error) {
      console.error('AI generation failed:', error);
      setAiError(error instanceof Error ? error.message : 'Wersee AI could not generate this draft.');
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleAiGenerate = () => runAiGeneration(aiPrompt, 'Shaping your custom request', 'listing.create_draft');

  const closeAiPrompt = () => {
    setShowAiPrompt(false);
    setAiProposal(null);
    setSelectedAiFields([]);
    setAiError('');
  };

  const applyAiProposal = () => {
    if (!aiProposal || !onAiApply) return;
    onAiApply(Object.fromEntries(selectedAiFields.map((key) => [key, aiProposal[key]])));
    setRecentAiFields(selectedAiFields);
    setActiveAiAction(`Updated ${selectedAiFields.length} listing field${selectedAiFields.length === 1 ? '' : 's'}`);
    setAiProposal(null);
    setSelectedAiFields([]);
    setAiPrompt('');
    setAiError('');
  };

  const renderAiValue = (value: unknown) => {
    if (Array.isArray(value)) return value.length ? value.map((item) => typeof item === 'string' ? item : JSON.stringify(item)).join(', ') : 'None';
    if (value && typeof value === 'object') return JSON.stringify(value);
    return value === undefined || value === null || value === '' ? 'Empty' : String(value);
  };

  const aiStatus = isAiLoading
    ? activeAiAction
    : aiProposal
      ? 'Draft ready for your review'
      : aiError
        ? 'AI needs another try'
        : activeAiAction;

  const listingMenuItems: CodexComposerMenuItem[] = aiQuickActions.map((action) => ({
    label: action.label,
    description: action.description,
    icon: action.icon,
    onSelect: () => {
      const request = aiPrompt.trim() ? `${action.prompt}\n\nUser idea or instructions: ${aiPrompt.trim()}` : action.prompt;
      void runAiGeneration(request, action.label, action.toolName);
    },
  }));

  const aiPanel = (
    <div className="relative flex h-full min-h-0 flex-col bg-[#080808]/68 text-white backdrop-blur-xl lg:bg-[#0b0b0b]">
      <div className="shrink-0 border-b border-white/[0.07] px-4 pb-4 pt-[max(14px,env(safe-area-inset-top))] sm:px-5 lg:pt-5">
        <div className="flex items-center gap-3">
          <button type="button" onClick={closeAiPrompt} aria-label="Back to listing" className="grid h-10 w-10 shrink-0 place-items-center rounded-full border border-white/[0.09] bg-black/25 text-zinc-300 transition hover:bg-white/[0.07] hover:text-white lg:hidden"><ArrowLeft className="h-4 w-4" /></button>
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2 text-sm font-semibold tracking-tight text-white"><Sparkles className="h-4 w-4" /> Listing AI</div>
            <p className="mt-0.5 truncate text-[11px] text-zinc-500">Build and review every step</p>
          </div>
          <button type="button" onClick={closeAiPrompt} aria-label="Close listing AI" className="hidden h-9 w-9 place-items-center rounded-full text-zinc-500 transition hover:bg-white/[0.07] hover:text-white lg:grid"><X className="h-4 w-4" /></button>
        </div>
        <CodexActivityPills active={isAiLoading} toolName={activeAiToolName} label={aiStatus} className="mt-4 hidden lg:flex" />
      </div>

      <div className="custom-scrollbar min-h-0 flex-1 overflow-y-auto px-4 pb-40 pt-5 sm:px-5 lg:pb-6">
        {!aiProposal ? (
          <div className="flex min-h-full flex-col justify-end pb-3 lg:justify-center lg:pb-8">
            <span className={`w-fit rounded-full border px-3 py-1.5 text-[9px] font-semibold uppercase tracking-[0.14em] ${activeStep?.required ? 'border-amber-300/15 bg-amber-300/[0.06] text-amber-200' : 'border-white/[0.08] bg-white/[0.04] text-zinc-500'}`}>{activeStep?.required ? 'Required step' : 'Optional step'}</span>
            <h3 className="mt-4 max-w-xs text-2xl font-medium tracking-[-0.035em] text-white">Create the listing with a clear idea.</h3>
            <p className="mt-3 max-w-sm text-sm leading-6 text-zinc-500">Describe the product, audience, tone, price, or what still needs work. Use + for focused actions.</p>
            <div className="mt-6 flex flex-wrap gap-2">
              {aiQuickActions.slice(0, 3).map((action) => (
                <button key={action.label} type="button" disabled={isAiLoading} onClick={() => void runAiGeneration(action.prompt, action.label, action.toolName)} className="rounded-full border border-white/[0.09] bg-black/35 px-3 py-2 text-xs font-medium text-zinc-400 transition hover:bg-white/[0.07] hover:text-white disabled:opacity-40">{action.label}</button>
              ))}
            </div>
          </div>
        ) : (
          <div>
            <div className="flex items-center justify-between gap-3">
              <div><p className="text-sm font-semibold text-white">Review proposed fields</p><p className="mt-1 text-xs text-zinc-500">Only checked fields will change.</p></div>
              <button type="button" onClick={() => { setAiProposal(null); setSelectedAiFields([]); }} className="rounded-full px-3 py-2 text-[11px] font-medium text-zinc-500 hover:bg-white/[0.05] hover:text-white">Start over</button>
            </div>
            <div className="mt-4 space-y-2">
              {Object.entries(aiProposal).map(([field, after]) => {
                const before = aiCurrentDraft[field];
                const selected = selectedAiFields.includes(field);
                return (
                  <label key={field} className={`block cursor-pointer rounded-[20px] border p-3 transition ${selected ? 'border-white/[0.2] bg-white/[0.07]' : 'border-white/[0.07] bg-black/20'}`}>
                    <div className="flex items-center gap-2"><input type="checkbox" checked={selected} onChange={() => setSelectedAiFields((current) => current.includes(field) ? current.filter((item) => item !== field) : [...current, field])} className="h-4 w-4 accent-white" /><span className="text-[11px] font-semibold capitalize text-zinc-200">{field.replace(/([A-Z])/g, ' $1')}</span></div>
                    <div className="mt-2 grid grid-cols-2 gap-2 text-[11px]"><div className="rounded-xl bg-black/30 p-2 text-zinc-600"><span className="mb-1 block text-[8px] uppercase tracking-[0.14em]">Current</span><span className="line-clamp-3 break-words">{renderAiValue(before)}</span></div><div className="rounded-xl bg-black/30 p-2 text-zinc-300"><span className="mb-1 block text-[8px] uppercase tracking-[0.14em] text-zinc-500">Proposed</span><span className="line-clamp-3 break-words">{renderAiValue(after)}</span></div></div>
                  </label>
                );
              })}
            </div>
          </div>
        )}

        {aiError && <div className="mt-4 rounded-[20px] border border-red-400/15 bg-red-400/[0.08] p-4"><p className="text-xs leading-5 text-red-100">{aiError}</p><button type="button" onClick={() => void runAiGeneration(aiPrompt.trim().length >= 3 ? aiPrompt : 'Fill the remaining listing fields.', 'Retrying the listing draft', activeAiToolName || 'listing.create_draft')} disabled={isAiLoading} className="mt-3 rounded-full border border-red-300/15 px-3 py-1.5 text-[11px] font-semibold text-red-100 hover:bg-red-300/10">Try again</button></div>}
      </div>

      <div className="absolute inset-x-0 bottom-0 z-20 bg-gradient-to-t from-black via-black/86 to-transparent px-3 pb-[max(10px,env(safe-area-inset-bottom))] pt-8 sm:px-4 lg:relative lg:shrink-0 lg:border-t lg:border-white/[0.07] lg:bg-[#0b0b0b] lg:px-4 lg:pb-4 lg:pt-3">
        <CodexExpandableActivityPill
          active={isAiLoading}
          toolName={activeAiToolName}
          label={aiStatus}
          detail={!isAiLoading && aiProposal ? (
            <span>{Object.keys(aiProposal).length} proposed fields are ready below. Select what should change, then apply the draft.</span>
          ) : undefined}
          className="mb-2 lg:hidden"
        />
        <AnimatePresence>
          {aiProposal && !isAiLoading && (
            <motion.div initial={{ opacity: 0, y: 12, scale: 0.96 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 8 }} className="mb-2 flex items-center gap-3 rounded-full border border-white/[0.11] bg-[#171719]/92 p-1.5 pl-4 shadow-xl backdrop-blur-3xl">
              <span className="min-w-0 flex-1 truncate text-xs font-medium text-white/65">{selectedAiFields.length} fields ready to apply</span>
              <button type="button" onClick={applyAiProposal} disabled={selectedAiFields.length === 0} className="flex h-9 shrink-0 items-center gap-1.5 rounded-full bg-white px-4 text-xs font-semibold text-black disabled:opacity-35">Apply <Check className="h-3.5 w-3.5" /></button>
            </motion.div>
          )}
        </AnimatePresence>
        <CodexComposer
          value={aiPrompt}
          onChange={(value) => {
            setAiPrompt(value);
            if (aiError) setAiError('');
          }}
          onSubmit={() => void handleAiGenerate()}
          disabled={isAiLoading}
          working={isAiLoading}
          reasoningLabel={activeAiAction}
          toolName={activeAiToolName}
          placeholder="Describe your listing…"
          maxLength={6000}
          menuItems={listingMenuItems}
        />
      </div>
    </div>
  );

  const aiModal = (
    <AnimatePresence>
      {showAiPrompt && isMobile && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-[200] bg-black/32 backdrop-blur-[3px] sm:p-3"
        >
          <motion.div
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'spring', damping: 30, stiffness: 260 }}
            className="ml-auto h-full w-full overflow-hidden border-white/[0.08] bg-transparent shadow-[-28px_0_70px_rgba(0,0,0,0.35)] sm:max-w-md sm:rounded-[28px] sm:border"
          >
            {aiPanel}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );

  if (variant === 'fullscreen') {
    return (
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-[100] flex flex-col overflow-hidden bg-[#050505] lg:flex-row"
      >
        <div className="relative flex h-full w-full flex-col border-white/[0.08] bg-[#0a0a0a] lg:w-[44%] lg:min-w-[520px] lg:border-r">
          {/* Header */}
          <header className="sticky top-0 z-20 border-b border-white/[0.07] bg-[#0a0a0a]/90 px-5 py-4 backdrop-blur-2xl sm:px-7">
            <div className="flex items-center justify-between gap-4">
              <div className="flex min-w-0 items-center gap-3">
              <button 
                onClick={onClose}
                aria-label="Close listing wizard"
                className="grid h-10 w-10 shrink-0 place-items-center rounded-full text-zinc-500 transition hover:bg-white/[0.07] hover:text-white active:scale-95"
              >
                <X className="h-[18px] w-[18px]" />
              </button>
              <div className="min-w-0">
                <p className="truncate text-sm font-semibold tracking-tight text-zinc-100">{title}</p>
                <p className="mt-0.5 text-xs text-zinc-500">Step {currentStep} of {totalSteps}</p>
              </div>
            </div>
              {hasAiAssistant && (
                <button
                  onClick={() => setShowAiPrompt((current) => !current)}
                  className={`flex h-10 items-center gap-2 rounded-full border px-3.5 text-xs font-semibold transition ${showAiPrompt ? 'border-white bg-white text-black' : 'border-white/[0.08] bg-white/[0.05] text-zinc-200 hover:bg-white/[0.09]'}`}
                  aria-label={showAiPrompt ? 'Show listing preview' : 'Open AI copilot'}
                >
                  {showAiPrompt ? <Eye className="h-4 w-4" /> : <Sparkles className="h-4 w-4" />}
                  <span className="hidden sm:inline">{showAiPrompt ? 'Preview' : 'AI Copilot'}</span>
                </button>
              )}
            </div>
            <nav className="custom-scrollbar mt-4 flex gap-2 overflow-x-auto pb-1" aria-label={`Listing steps, step ${currentStep} of ${totalSteps}`}>
              {wizardSteps.map((item, index) => {
                const isCurrent = index + 1 === currentStep;
                const isComplete = index + 1 < currentStep;
                return <div key={`${item.label}-${index}`} aria-current={isCurrent ? 'step' : undefined} className={`flex shrink-0 items-center gap-2 rounded-full border px-2.5 py-1.5 transition ${isCurrent ? 'border-white/[0.2] bg-white/[0.09] text-white' : 'border-white/[0.06] bg-white/[0.025] text-zinc-600'}`}>
                  <span className={`grid h-4 w-4 place-items-center rounded-full text-[9px] font-bold ${isComplete ? 'bg-emerald-400 text-black' : isCurrent ? 'bg-white text-black' : 'bg-white/[0.07] text-zinc-600'}`}>{isComplete ? <Check className="h-2.5 w-2.5" /> : index + 1}</span>
                  <span className="max-w-28 truncate text-[10px] font-medium">{item.label}</span>
                  <span className={`text-[8px] font-semibold uppercase tracking-[0.11em] ${item.required ? (isCurrent ? 'text-amber-300' : 'text-zinc-700') : 'text-zinc-700'}`}>{item.required ? 'Required' : 'Optional'}</span>
                </div>;
              })}
            </nav>
          </header>

          {/* Content Area */}
          <main className="custom-scrollbar relative flex-1 overflow-y-auto px-5 py-8 sm:px-8 sm:py-10 lg:px-10">
            <AnimatePresence mode="wait">
              <motion.div
                key={currentStep}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.4, ease: [0.23, 1, 0.32, 1] }}
                className="mx-auto max-w-xl"
              >
                {(activeStepTitle || stepDescription) && (
                  <div className="mb-8">
                    <span className={`mb-3 inline-flex rounded-full border px-2.5 py-1 text-[9px] font-semibold uppercase tracking-[0.14em] ${activeStep?.required ? 'border-amber-300/15 bg-amber-300/[0.06] text-amber-200' : 'border-white/[0.07] bg-white/[0.03] text-zinc-500'}`}>{activeStep?.required ? 'Required step' : 'Optional step'}</span>
                    {activeStepTitle && <h1 className="text-3xl font-semibold tracking-[-0.035em] text-white sm:text-[2.1rem]">{activeStepTitle}</h1>}
                    {stepDescription && <p className="mt-2 max-w-lg text-sm leading-6 text-zinc-500">{stepDescription}</p>}
                    {recentAiFields.length > 0 && <p className="mt-3 truncate text-xs font-medium text-zinc-400" title={recentAiFields.join(', ')}>AI updated {recentAiFields.join(', ')}</p>}
                  </div>
                )}
                {children}
              </motion.div>
            </AnimatePresence>
          </main>

          <footer className="sticky bottom-0 z-20 flex items-center justify-between border-t border-white/[0.07] bg-[#0a0a0a]/90 px-5 py-4 backdrop-blur-2xl sm:px-8">
            <motion.button
              whileTap={{ scale: 0.95 }}
              onClick={onBack}
              disabled={isFirstStep}
              className={`flex h-11 items-center gap-2 rounded-full px-4 text-sm font-medium transition-all ${
                isFirstStep 
                  ? 'cursor-not-allowed text-zinc-800' 
                  : 'text-zinc-400 hover:bg-white/[0.06] hover:text-white'
              }`}
            >
              <ArrowLeft className="w-4 h-4" /> Back
            </motion.button>
            
            <motion.button
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              onClick={onNext}
              disabled={loading}
              className="flex h-11 min-w-32 items-center justify-center gap-2 rounded-full bg-white px-6 text-sm font-semibold text-black shadow-sm transition-all hover:bg-zinc-200 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {loading ? (
                <div className="w-4 h-4 border-2 border-t-transparent rounded-full animate-spin border-black" />
              ) : isLastStep ? (
                <>Publish Listing <Check className="w-4 h-4" /></>
              ) : (
                <>Continue <ArrowRight className="w-4 h-4" /></>
              )}
            </motion.button>
          </footer>
        </div>

        <aside className="relative hidden flex-1 items-center justify-center overflow-hidden bg-[#050505] p-10 lg:flex">
          <div className="absolute left-1/2 top-6 z-20 flex -translate-x-1/2 items-center rounded-full border border-white/[0.08] bg-white/[0.05] p-1 backdrop-blur-2xl">
            {(['card', 'page', 'email', 'checkout'] as const).map(tab => (
              <button
                key={tab}
                onClick={() => setPreviewType(tab)}
                className={`rounded-full px-4 py-2 text-xs font-medium capitalize transition-all ${previewType === tab ? 'bg-white text-black' : 'text-zinc-500 hover:text-zinc-200'}`}
              >
                {tab}
              </button>
            ))}
          </div>

          <div className="absolute right-6 top-6 z-20 flex items-center rounded-full border border-white/[0.08] bg-white/[0.05] p-1">
            <button onClick={() => setPreviewDevice('mobile')} aria-label="Mobile preview" className={`grid h-8 w-8 place-items-center rounded-full transition-all ${previewDevice === 'mobile' ? 'bg-white/10 text-white' : 'text-zinc-500 hover:text-zinc-200'}`}><Smartphone className="w-4 h-4" /></button>
            <button onClick={() => setPreviewDevice('desktop')} aria-label="Desktop preview" className={`grid h-8 w-8 place-items-center rounded-full transition-all ${previewDevice === 'desktop' ? 'bg-white/10 text-white' : 'text-zinc-500 hover:text-zinc-200'}`}><Monitor className="w-4 h-4" /></button>
          </div>

          {/* Preview Frame */}
          <motion.div 
            layout
            className={`relative z-10 overflow-hidden rounded-[28px] border border-white/10 bg-[#0A0A0A] shadow-2xl transition-all duration-500 ${
              previewDevice === 'mobile' ? 'h-[667px] w-[375px] max-w-full' : 'h-[600px] w-full max-w-[800px]'
            }`}
          >
            <div className="h-full overflow-y-auto custom-scrollbar">
              {typeof preview === 'function' ? preview(previewType, isPreviewDark) : preview}
            </div>
          </motion.div>

          <div className="absolute bottom-6 flex items-center gap-2 text-[10px] font-semibold uppercase tracking-[0.18em] text-zinc-700">
            <div className="h-1.5 w-1.5 rounded-full bg-emerald-500" />
            Live Preview
          </div>
          <AnimatePresence>
            {showAiPrompt && hasAiAssistant && (
              <motion.div
                initial={{ x: '100%', opacity: 0 }}
                animate={{ x: 0, opacity: 1 }}
                exit={{ x: '100%', opacity: 0 }}
                transition={{ type: 'spring', damping: 30, stiffness: 260 }}
                className="absolute inset-y-0 right-0 z-30 w-full max-w-[410px] border-l border-white/[0.08] shadow-[-28px_0_70px_rgba(0,0,0,0.45)]"
              >
                {aiPanel}
              </motion.div>
            )}
          </AnimatePresence>
        </aside>
        {aiModal}
      </motion.div>
    );
  }

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6">
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="absolute inset-0 bg-black/30 backdrop-blur-sm"
        onClick={onClose}
      />
      
      <motion.div
        initial={{ opacity: 0, scale: 0.9, y: 20 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.9, y: 20 }}
        transition={{ type: 'spring', damping: 25, stiffness: 300 }}
        className={`relative w-full max-w-lg sm:max-w-2xl md:max-w-4xl rounded-3xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh] ${isDark ? 'bg-[#141414]' : 'bg-white'}`}
      >
        {/* Header */}
        <div className={`flex items-center justify-between p-6 border-b z-10 ${isDark ? 'border-white/10 bg-[#141414]' : 'border-gray-100 bg-white'}`}>
          <div className="flex items-center gap-4">
            <button 
              onClick={onClose}
              className={`p-2 rounded-full transition-colors ${isDark ? 'hover:bg-white/10 text-white' : 'hover:bg-gray-100 text-gray-500'}`}
            >
              <X className="w-5 h-5" />
            </button>
            <div>
              <motion.h2 
                key={title}
                initial={{ opacity: 0, y: 5 }}
                animate={{ opacity: 1, y: 0 }}
                className={`text-xl font-bold ${isDark ? 'text-white' : 'text-[#1D1D1F]'}`}
              >
                {title}
              </motion.h2>
              <div className={`flex items-center gap-2 text-sm mt-1 ${isDark ? 'text-gray-400' : 'text-gray-500'}`}>
                <span className={`font-medium ${isDark ? 'text-white' : 'text-[#1D1D1F]'}`}>Step {currentStep}</span>
                <span>of {totalSteps}</span>
              </div>
              {recentAiFields.length > 0 && <p className="mt-1 max-w-[320px] truncate text-xs font-semibold text-indigo-500" title={recentAiFields.join(', ')}>AI updated: {recentAiFields.join(', ')}</p>}
            </div>
          </div>
          
            {/* Progress Bar */}
          <div className="hidden sm:flex items-center gap-4">
            {hasAiAssistant && (
              <button
                onClick={() => setShowAiPrompt(true)}
                className="p-2 bg-indigo-500/10 text-indigo-400 rounded-xl hover:bg-indigo-500/20 transition-colors"
                title="Create with AI"
              >
                <Sparkles className="w-5 h-5" />
              </button>
            )}
            <div className="flex items-center gap-1">
              {Array.from({ length: totalSteps }).map((_, i) => (
                <motion.div
                  key={i}
                  initial={false}
                  animate={{ 
                    backgroundColor: i + 1 <= currentStep 
                      ? (isDark ? '#FFFFFF' : '#1D1D1F') 
                      : (isDark ? 'rgba(255,255,255,0.1)' : '#E5E7EB'),
                    scale: i + 1 === currentStep ? 1.1 : 1
                  }}
                  className="h-1.5 w-8 rounded-full"
                />
              ))}
            </div>
          </div>
        </div>

        {/* Content */}
        <div className={`flex-1 overflow-y-auto p-6 sm:p-10 ${isDark ? 'bg-[#0A0A0A]' : 'bg-[#F5F5F7]'}`}>
          <AnimatePresence mode="wait">
            <motion.div
              key={currentStep}
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -20 }}
              transition={{ duration: 0.3 }}
              className="max-w-2xl mx-auto"
            >
              {children}
            </motion.div>
          </AnimatePresence>
        </div>

        {/* Footer */}
        <div className={`p-6 border-t flex justify-between items-center z-10 ${isDark ? 'border-white/10 bg-[#141414]' : 'border-gray-100 bg-white'}`}>
          <button
            onClick={onBack}
            disabled={isFirstStep}
            className={`flex items-center gap-2 px-6 py-3 rounded-xl font-medium transition-colors ${
              isFirstStep 
                ? 'text-gray-300 cursor-not-allowed' 
                : isDark 
                  ? 'text-white hover:bg-white/10' 
                  : 'text-[#1D1D1F] hover:bg-gray-100'
            }`}
          >
            <ArrowLeft className="w-4 h-4" /> Back
          </button>
          
          <button
            onClick={onNext}
            disabled={loading}
            className={`flex items-center gap-2 px-8 py-3 rounded-xl font-bold transition-all active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed shadow-lg ${
              isDark 
                ? 'bg-gradient-to-r from-white to-gray-200 text-black shadow-white/10' 
                : 'bg-gradient-to-r from-[#1D1D1F] to-[#333333] text-white shadow-black/10'
            }`}
          >
            {loading ? (
              <div className={`w-5 h-5 border-2 border-t-transparent rounded-full animate-spin ${isDark ? 'border-black' : 'border-white'}`} />
            ) : isLastStep ? (
              <>Publish <Check className="w-4 h-4" /></>
            ) : (
              <>Next <ArrowRight className="w-4 h-4" /></>
            )}
          </button>
        </div>
      </motion.div>
      {aiModal}
    </div>
  );
};
