import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import {
  ArrowUp,
  BarChart3,
  BriefcaseBusiness,
  Check,
  CircleDollarSign,
  FileText,
  FolderSearch2,
  Globe2,
  History,
  ListChecks,
  LucideIcon,
  MessageSquarePlus,
  Navigation,
  PackageSearch,
  Plus,
  Search,
  Settings2,
  ShieldCheck,
  Sparkles,
  Square,
  Users,
  WandSparkles,
  Wrench,
} from 'lucide-react';

export interface CodexComposerMenuItem {
  label: string;
  description?: string;
  icon?: LucideIcon;
  onSelect: () => void;
}

interface CodexActivityPillsProps {
  active?: boolean;
  label: string;
  toolName?: string;
  className?: string;
}

interface CodexExpandableActivityPillProps extends CodexActivityPillsProps {
  detail?: React.ReactNode;
}

interface CodexComposerProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: () => void;
  onStop?: () => void;
  disabled?: boolean;
  working?: boolean;
  reasoningLabel?: string;
  toolName?: string;
  placeholder?: string;
  maxLength?: number;
  menuItems?: CodexComposerMenuItem[];
  textareaRef?: React.RefObject<HTMLTextAreaElement | null>;
  className?: string;
}

const toolIcon = (toolName?: string): LucideIcon => {
  const value = (toolName || '').toLowerCase();
  if (value.includes('analytics') || value.includes('performance') || value.includes('sales')) return BarChart3;
  if (value.includes('listing') || value.includes('product')) return PackageSearch;
  if (value.includes('navigation') || value.includes('open')) return Navigation;
  if (value.includes('invoice') || value.includes('payment') || value.includes('money')) return CircleDollarSign;
  if (value.includes('community') || value.includes('team') || value.includes('crm') || value.includes('customer')) return Users;
  if (value.includes('storage') || value.includes('file')) return FolderSearch2;
  if (value.includes('website') || value.includes('business')) return Globe2;
  if (value.includes('form') || value.includes('proposal') || value.includes('contract') || value.includes('wiki')) return FileText;
  if (value.includes('automation') || value.includes('workflow')) return Wrench;
  if (value.includes('check') || value.includes('review')) return ListChecks;
  return WandSparkles;
};

export const humanizeAiTool = (toolName?: string) => {
  const value = (toolName || '').toLowerCase();
  if (!value) return 'Thinking through your request';
  if (value.includes('analytics') || value.includes('performance') || value.includes('sales')) return 'Reading live performance data';
  if (value.includes('listing') || value.includes('product')) return 'Working with your listings';
  if (value.includes('navigation')) return 'Opening the right workspace view';
  if (value.includes('invoice') || value.includes('payment') || value.includes('money')) return 'Checking your finance workspace';
  if (value.includes('community')) return 'Reviewing your communities';
  if (value.includes('team')) return 'Reviewing your workspace team';
  if (value.includes('storage') || value.includes('file')) return 'Searching your workspace files';
  if (value.includes('website')) return 'Reviewing your websites';
  if (value.includes('business')) return 'Reading your business context';
  if (value.includes('automation') || value.includes('workflow')) return 'Reviewing your automations';
  if (value.includes('check') || value.includes('review')) return 'Checking every required detail';
  return `Using ${toolName?.replaceAll('.', ' ')}`;
};

const NineDotMark: React.FC<{ active?: boolean }> = ({ active }) => (
  <div className="grid grid-cols-3 gap-[3px]" aria-hidden="true">
    {Array.from({ length: 9 }).map((_, index) => (
      <motion.span
        key={index}
        className="h-[3px] w-[3px] rounded-full bg-current"
        animate={{
          opacity: active ? [0.22, 1, 0.22] : [0.28, 0.72, 0.28],
          scale: active ? [0.72, 1.5, 0.72] : [0.88, 1.1, 0.88],
        }}
        transition={{
          duration: active ? 0.82 : 2.4,
          repeat: Infinity,
          delay: index * (active ? 0.055 : 0.11),
          ease: 'easeInOut',
        }}
      />
    ))}
  </div>
);

const ToolMark: React.FC<{ toolName: string }> = ({ toolName }) => {
  const Icon = toolIcon(toolName);
  return (
    <motion.span
      initial={{ opacity: 0, scale: 0.45, rotate: -18 }}
      animate={{ opacity: 1, scale: 1, rotate: 0 }}
      exit={{ opacity: 0, scale: 0.5, rotate: 18 }}
      transition={{ type: 'spring', damping: 18, stiffness: 280 }}
      className="relative grid h-5 w-5 place-items-center"
      aria-hidden="true"
    >
      <motion.span
        className="absolute inset-0 rounded-full border border-white/30"
        animate={{ scale: [0.72, 1.3, 0.72], opacity: [0.55, 0, 0.55] }}
        transition={{ duration: 1.55, repeat: Infinity, ease: 'easeOut' }}
      />
      <motion.span
        className="absolute -right-0.5 -top-0.5 h-1.5 w-1.5 rounded-full bg-white"
        animate={{ rotate: 360, transformOrigin: '-7px 7px' }}
        transition={{ duration: 1.8, repeat: Infinity, ease: 'linear' }}
      />
      <Icon className="h-4 w-4" strokeWidth={1.8} />
    </motion.span>
  );
};

export const CodexActivityPills: React.FC<CodexActivityPillsProps> = ({
  active = false,
  label,
  toolName,
  className = '',
}) => (
  <div className={`flex min-w-0 items-center gap-2 ${className}`} aria-live="polite">
    <div className="flex h-10 w-12 shrink-0 items-center justify-center rounded-full border border-white/[0.1] bg-black/45 text-white shadow-[inset_0_1px_0_rgba(255,255,255,0.05)] backdrop-blur-2xl">
      <AnimatePresence mode="wait" initial={false}>
        {active && toolName ? <ToolMark key={toolName} toolName={toolName} /> : <motion.span key="dots" initial={{ opacity: 0, scale: 0.7 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.7 }}><NineDotMark active={active} /></motion.span>}
      </AnimatePresence>
    </div>
    <motion.div
      key={`${toolName || 'dots'}-${label}`}
      initial={{ opacity: 0, y: 4 }}
      animate={{ opacity: 1, y: 0 }}
      className="flex h-10 min-w-0 flex-1 items-center rounded-full border border-white/[0.1] bg-black/45 px-4 text-xs font-medium text-white/72 shadow-[inset_0_1px_0_rgba(255,255,255,0.05)] backdrop-blur-2xl"
    >
      <span className="truncate">{label}</span>
    </motion.div>
  </div>
);

export const CodexExpandableActivityPill: React.FC<CodexExpandableActivityPillProps> = ({
  active = false,
  label,
  toolName,
  detail,
  className = '',
}) => (
  <motion.div
    layout
    transition={{ layout: { type: 'spring', stiffness: 320, damping: 30 } }}
    className={`overflow-hidden rounded-[28px] border border-white/[0.11] bg-[#141416]/94 p-1.5 text-white shadow-[0_20px_55px_rgba(0,0,0,0.48)] backdrop-blur-3xl ${className}`}
    aria-live="polite"
  >
    <div className="flex min-w-0 items-center gap-2">
      <div className="flex h-10 w-12 shrink-0 items-center justify-center rounded-full border border-white/[0.09] bg-black/35 text-white">
        <AnimatePresence mode="wait" initial={false}>
          {active && toolName ? <ToolMark key={toolName} toolName={toolName} /> : <motion.span key="dots" initial={{ opacity: 0, scale: 0.72 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.72 }}><NineDotMark active={active} /></motion.span>}
        </AnimatePresence>
      </div>
      <motion.div key={`${toolName || 'dots'}-${label}`} initial={{ opacity: 0, y: 3 }} animate={{ opacity: 1, y: 0 }} className="min-w-0 flex-1 px-2 pr-3 text-xs font-medium text-white/72">
        <span className="block truncate">{label}</span>
      </motion.div>
    </div>
    <AnimatePresence initial={false}>
      {detail ? (
        <motion.div
          key="detail"
          initial={{ height: 0, opacity: 0, y: -6 }}
          animate={{ height: 'auto', opacity: 1, y: 0 }}
          exit={{ height: 0, opacity: 0, y: -4 }}
          transition={{ height: { type: 'spring', stiffness: 300, damping: 31 }, opacity: { duration: 0.18 } }}
          className="overflow-hidden"
        >
          <div className="mx-2 mt-1 border-t border-white/[0.08] px-2 pb-2 pt-3 text-sm leading-6 text-white/78">
            {detail}
          </div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  </motion.div>
);

export const CodexComposer: React.FC<CodexComposerProps> = ({
  value,
  onChange,
  onSubmit,
  onStop,
  disabled = false,
  working = false,
  reasoningLabel = 'Thinking through your request',
  toolName,
  placeholder = 'Ask Wersee AI anything…',
  maxLength,
  menuItems = [],
  textareaRef,
  className = '',
}) => {
  const [menuOpen, setMenuOpen] = useState(false);
  const [isMultiline, setIsMultiline] = useState(false);
  const localRef = useRef<HTMLTextAreaElement | null>(null);
  const menuRef = useRef<HTMLDivElement | null>(null);

  const assignRef = (node: HTMLTextAreaElement | null) => {
    localRef.current = node;
    if (textareaRef) textareaRef.current = node;
  };

  useEffect(() => {
    const input = localRef.current;
    if (!input) return;
    input.style.height = 'auto';
    const nextHeight = Math.min(Math.max(input.scrollHeight, 24), 144);
    input.style.height = `${nextHeight}px`;
    setIsMultiline(nextHeight > 30 || value.includes('\n'));
  }, [value]);

  useEffect(() => {
    if (!menuOpen) return;
    const close = (event: PointerEvent) => {
      if (!menuRef.current?.contains(event.target as Node)) setMenuOpen(false);
    };
    window.addEventListener('pointerdown', close);
    return () => window.removeEventListener('pointerdown', close);
  }, [menuOpen]);

  const resolvedItems = useMemo(() => menuItems.filter(Boolean), [menuItems]);
  const canSend = Boolean(value.trim()) && !disabled && !working;

  return (
    <div className={`flex items-end gap-2 ${className}`}>
      <div ref={menuRef} className="relative shrink-0">
        <AnimatePresence>
          {menuOpen && (
            <motion.div
              initial={{ opacity: 0, y: 14, scale: 0.92 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 10, scale: 0.94 }}
              transition={{ type: 'spring', stiffness: 340, damping: 27 }}
              className="absolute bottom-full left-0 z-30 mb-3 w-[min(78vw,290px)] origin-bottom-left overflow-hidden rounded-[24px] border border-white/[0.1] bg-[#111113]/95 p-2 shadow-[0_24px_65px_rgba(0,0,0,0.55)] backdrop-blur-3xl"
              role="menu"
            >
              {resolvedItems.map((item) => {
                const Icon = item.icon || Sparkles;
                return (
                  <button
                    key={item.label}
                    type="button"
                    role="menuitem"
                    onClick={() => {
                      setMenuOpen(false);
                      item.onSelect();
                    }}
                    className="flex w-full items-center gap-3 rounded-[17px] px-3 py-2.5 text-left transition hover:bg-white/[0.065]"
                  >
                    <span className="grid h-9 w-9 shrink-0 place-items-center rounded-full border border-white/[0.08] bg-white/[0.04] text-white/70"><Icon className="h-4 w-4" /></span>
                    <span className="min-w-0"><span className="block text-xs font-semibold text-white/90">{item.label}</span>{item.description && <span className="mt-0.5 block truncate text-[10px] text-white/35">{item.description}</span>}</span>
                  </button>
                );
              })}
            </motion.div>
          )}
        </AnimatePresence>
        <motion.button
          type="button"
          whileTap={{ scale: 0.9 }}
          onClick={() => setMenuOpen((open) => !open)}
          className={`grid h-12 w-12 place-items-center rounded-full border text-white shadow-[0_12px_35px_rgba(0,0,0,0.35)] backdrop-blur-2xl transition ${menuOpen ? 'border-white/20 bg-white text-black' : 'border-white/[0.11] bg-[#141416]/90 hover:bg-[#1b1b1e]'}`}
          aria-label="Open AI actions"
          aria-haspopup="menu"
          aria-expanded={menuOpen}
        >
          <Plus className={`h-5 w-5 transition-transform duration-300 ${menuOpen ? 'rotate-45' : ''}`} />
        </motion.button>
      </div>

      <div className={`min-w-0 flex-1 rounded-[25px] border border-white/[0.11] bg-[#141416]/92 p-1.5 shadow-[0_18px_50px_rgba(0,0,0,0.4)] backdrop-blur-3xl transition-all focus-within:border-white/20 ${isMultiline ? 'rounded-[28px]' : ''}`}>
        <div className={`flex min-h-9 items-end gap-2 ${isMultiline ? 'pl-3' : 'pl-3.5'}`}>
          {working ? (
            <div className="flex min-h-9 min-w-0 flex-1 items-center gap-2 py-1 text-xs font-medium text-white/62" aria-live="polite">
              <AnimatePresence mode="wait" initial={false}>
                {toolName ? <ToolMark key={toolName} toolName={toolName} /> : <motion.span key="reasoning-dots"><NineDotMark active /></motion.span>}
              </AnimatePresence>
              <motion.span key={reasoningLabel} initial={{ opacity: 0, y: 3 }} animate={{ opacity: 1, y: 0 }} className="truncate">{reasoningLabel}</motion.span>
            </div>
          ) : (
            <textarea
              ref={assignRef}
              value={value}
              onChange={(event) => onChange(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' && !event.shiftKey) {
                  event.preventDefault();
                  if (canSend) onSubmit();
                }
              }}
              rows={1}
              maxLength={maxLength}
              placeholder={placeholder}
              className="max-h-36 min-h-6 min-w-0 flex-1 resize-none overflow-y-auto bg-transparent py-2 text-[15px] leading-6 text-white outline-none placeholder:text-white/28"
            />
          )}
          <motion.button
            type="button"
            whileTap={{ scale: 0.9 }}
            onClick={() => working ? onStop?.() : onSubmit()}
            disabled={working ? !onStop : !canSend}
            className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-white text-black transition hover:bg-zinc-200 disabled:bg-white/[0.08] disabled:text-white/25"
            aria-label={working ? 'Stop AI' : 'Send message'}
          >
            {working ? <Square className="h-3.5 w-3.5 fill-current" /> : <ArrowUp className="h-4 w-4" strokeWidth={2.4} />}
          </motion.button>
        </div>
      </div>
    </div>
  );
};

export const codexComposerIcons = {
  Sparkles,
  History,
  MessageSquarePlus,
  Settings2,
  ShieldCheck,
  BriefcaseBusiness,
  Check,
  Search,
};
